let hooks = [];
let cursor = 0;

function useState(initial) {
  const idx = cursor++;
  if (hooks[idx] === undefined) hooks[idx] = initial;
  const setState = (value) => { hooks[idx] = value; };
  return [hooks[idx], setState];
}

function render(Component) {
  cursor = 0;
  return Component();
}

let showAge = true;
let setNameLater;

function Profile() {
  let age = null;
  if (showAge) {
    const [a] = useState(30);
    age = a;
  }
  const [name, setName] = useState('Ana');
  setNameLater = setName;
  return name + ':' + age;
}

